function decodeBase64(parts) {
  const raw = atob(parts.join(""));
  return Uint8Array.from(raw, (character) => character.charCodeAt(0));
}
export function hanriverRollExampleBytes() {
  if (!globalThis.fflate) throw new Error("ZIP 도구를 불러오지 못했어요.");
  const entries = Object.fromEntries(SCAN_BASE64.map(([name, parts]) => [name, decodeBase64(parts)]));
  return {
    zipBytes: globalThis.fflate.zipSync(entries, { level: 0, mtime: new Date(Date.UTC(1980, 0, 1)) }),
    recordBytes: new TextEncoder().encode(SHOOTING_RECORD_CSV),
  };
}
